package com.newzkl.platform.base.biz.order.model.vo;import lombok.Data;import java.io.Serializable;import java.time.LocalDateTime;/** * 售后操作记录-视图对象（返回给前端） * * @author sijiwang * @since 2026-01-23 */@Datapublic class RefundOperationRecordVO implements Serializable {    private static final long serialVersionUID = 1L;    /**     * 主键ID     */    private Long id;    /**     * spu订单id     */    private Long spuOrderId;    /**     * 售后单refund表的主键     */    private Long refundId;    /**     * 操作人ID     */    private Long operatorId;    /**     * 操作方角色编码（对应RoleEnum.CompanyRole的code：1000=C端客户，1001=供应商，1002=渠道商，0=平台等）     */    private Long operatorRoleCode;    /**     * 操作方客户端类型（对应CommonEnum.Client的code：user=用户端，supplier=供应商端，channel=渠道商端，admin=平台端等）     */    private String operatorClient;    /**     * 操作方名称     */    private String operatorName;    /**     * 操作前售后单状态0 ->待渠道商审核 1->待商户审核 2->待供应商审核 4->待提交物流 6->待确认收货 7->待平台介入 8 -> 平台介入中 9 -> 退款中 10 -> 已完成 -2 -> 已拒绝 -4->已关闭     */    private Integer beforeState;    /**     * 操作后售后单状态0 ->待渠道商审核 1->待商户审核 2->待供应商审核 4->待提交物流 6->待确认收货 7->待平台介入 8 -> 平台介入中 9 -> 退款中 10 -> 已完成 -2 -> 已拒绝 -4->已关闭     */    private Integer afterState;    /**     * 操作类型（0=发起退款申请，1=审核通过，2=审核拒绝，3=提交物流信息，4=确认收货，5=退款完成，6=关闭售后，7=平台介入）     */    private Integer operationType;    /**     * 操作内容描述     */    private String operationContent;    /**     * 本次操作涉及的退款金额     */    private Integer refundAmount;    /**     * 物流公司名称     */    private String freightCompanyName;    /**     * 物流单号     */    private String freightNo;    /**     * 操作原因/备注     */    private String reason;    /**     * 操作时间     */    private LocalDateTime createTime;    /**     * 更新时间     */    private LocalDateTime updateTime;    /**     * 拓展字段（JSON格式）     */    private String ext;}